const std = @import("std");
const math = std.math;
const Allocator = std.mem.Allocator;

pub const Config = struct {
    dim: usize,
    depth: usize,
    head_dim: usize,
    heads: usize,
    vocab_size: usize,
    context_limit: usize,
    epsilon: f32 = 1e-6,
};

pub const Tensor = struct {
    data: []f32,
    shape: []const usize,
    allocator: Allocator,

    pub fn init(allocator: Allocator, shape: []const usize) !Tensor {
        var size: usize = 1;
        for (shape) |s| size *= s;
        const data = try allocator.alloc(f32, size);
        const shape_clone = try allocator.dupe(usize, shape);
        @memset(data, 0);
        return Tensor{ .data = data, .shape = shape_clone, .allocator = allocator };
    }

    pub fn deinit(self: *Tensor) void {
        self.allocator.free(self.data);
        self.allocator.free(self.shape);
    }

    pub fn get(self: Tensor, indices: []const usize) f32 {
        var idx: usize = 0;
        var stride: usize = 1;
        var i: usize = self.shape.len;
        while (i > 0) {
            i -= 1;
            idx += indices[i] * stride;
            stride *= self.shape[i];
        }
        return self.data[idx];
    }

    pub fn set(self: *Tensor, indices: []const usize, value: f32) void {
        var idx: usize = 0;
        var stride: usize = 1;
        var i: usize = self.shape.len;
        while (i > 0) {
            i -= 1;
            idx += indices[i] * stride;
            stride *= self.shape[i];
        }
        self.data[idx] = value;
    }
};

pub const ResonanceMemory = struct {
    dim: usize,
    allocator: Allocator,
    weights_real: Tensor,
    weights_imag: Tensor,
    scale: f32,

    pub fn init(allocator: Allocator, dim: usize) !ResonanceMemory {
        const shape = [_]usize{dim, dim};
        var w_real = try Tensor.init(allocator, &shape);
        var w_imag = try Tensor.init(allocator, &shape);

        var prng = std.rand.DefaultPrng.init(42);
        const random = prng.random();

        for (w_real.data) |*x| x.* = (random.float(f32) - 0.5) * 0.02;
        for (w_imag.data) |*x| x.* = (random.float(f32) - 0.5) * 0.02;

        return ResonanceMemory{
            .dim = dim,
            .allocator = allocator,
            .weights_real = w_real,
            .weights_imag = w_imag,
            .scale = 1.0 / @sqrt(@as(f32, @floatFromInt(dim))),
        };
    }

    pub fn deinit(self: *ResonanceMemory) void {
        self.weights_real.deinit();
        self.weights_imag.deinit();
    }

    pub fn forward(self: *ResonanceMemory, input: Tensor, output: *Tensor) !void {
        const batch = input.shape[0];
        const seq = input.shape[1];
        const d = input.shape[2];

        const input_indices = [_]usize{0, 0, 0};
        var out_indices = [_]usize{0, 0, 0};

        var b: usize = 0;
        while (b < batch) : (b += 1) {
            var t: usize = 0;
            while (t < seq) : (t += 1) {
                var i: usize = 0;
                while (i < d) : (i += 1) {
                    var sum_r: f32 = 0;
                    var j: usize = 0;
                    while (j < d) : (j += 1) {
                        const inp_idx = [_]usize{b, t, j};
                        const w_idx = [_]usize{i, j};
                        const val = input.get(&inp_idx);
                        const wr = self.weights_real.get(&w_idx);
                        const wi = self.weights_imag.get(&w_idx);

                        const phase = val * self.scale;
                        const rot_r = @cos(phase) * wr - @sin(phase) * wi;
                        sum_r += rot_r;
                    }
                    out_indices[0] = b;
                    out_indices[1] = t;
                    out_indices[2] = i;
                    output.set(&out_indices, sum_r);
                }
            }
        }
    }
};

pub const CausalConv1D = struct {
    allocator: Allocator,
    kernel: Tensor,
    kernel_size: usize,
    dim: usize,

    pub fn init(allocator: Allocator, dim: usize, kernel_size: usize) !CausalConv1D {
        const shape = [_]usize{dim, kernel_size};
        var k = try Tensor.init(allocator, &shape);

        var prng = std.rand.DefaultPrng.init(123);
        const random = prng.random();
        for (k.data) |*x| x.* = (random.float(f32) - 0.5) * 0.1;

        return CausalConv1D{
            .allocator = allocator,
            .kernel = k,
            .kernel_size = kernel_size,
            .dim = dim,
        };
    }

    pub fn deinit(self: *CausalConv1D) void {
        self.kernel.deinit();
    }

    pub fn forward(self: *CausalConv1D, input: Tensor, output: *Tensor) !void {
        const batch = input.shape[0];
        const seq = input.shape[1];
        const d = input.shape[2];

        var b: usize = 0;
        while (b < batch) : (b += 1) {
            var t: usize = 0;
            while (t < seq) : (t += 1) {
                var c: usize = 0;
                while (c < d) : (c += 1) {
                    var sum: f32 = 0;
                    var k: usize = 0;
                    while (k < self.kernel_size) : (k += 1) {
                        if (t >= k) {
                            const in_idx = [_]usize{b, t - k, c};
                            const k_idx = [_]usize{c, k};
                            sum += input.get(&in_idx) * self.kernel.get(&k_idx);
                        }
                    }
                    const out_idx = [_]usize{b, t, c};
                    output.set(&out_idx, sum);
                }
            }
        }
    }
};

pub const RGAMLayer = struct {
    allocator: Allocator,
    dim: usize,
    conv: CausalConv1D,
    memory: ResonanceMemory,
    gate_w: Tensor,
    norm: Tensor,

    pub fn init(allocator: Allocator, config: Config) !RGAMLayer {
        const conv = try CausalConv1D.init(allocator, config.dim, 4);
        const memory = try ResonanceMemory.init(allocator, config.dim);
        const g_shape = [_]usize{config.dim * 2, config.dim};
        var gw = try Tensor.init(allocator, &g_shape);
        const n_shape = [_]usize{config.dim};
        var n = try Tensor.init(allocator, &n_shape);

        @memset(n.data, 1.0);

        return RGAMLayer{
            .allocator = allocator,
            .dim = config.dim,
            .conv = conv,
            .memory = memory,
            .gate_w = gw,
            .norm = n,
        };
    }

    pub fn deinit(self: *RGAMLayer) void {
        self.conv.deinit();
        self.memory.deinit();
        self.gate_w.deinit();
        self.norm.deinit();
    }

    fn silu(x: f32) f32 {
        return x / (1.0 + @exp(-x));
    }

    fn sigmoid(x: f32) f32 {
        return 1.0 / (1.0 + @exp(-x));
    }

    pub fn forward(self: *RGAMLayer, input: Tensor, output: *Tensor) !void {
        const batch = input.shape[0];
        const seq = input.shape[1];
        const d = self.dim;

        var conv_out = try Tensor.init(self.allocator, input.shape);
        defer conv_out.deinit();
        try self.conv.forward(input, &conv_out);

        var mem_out = try Tensor.init(self.allocator, input.shape);
        defer mem_out.deinit();
        try self.memory.forward(input, &mem_out);

        var b: usize = 0;
        while (b < batch) : (b += 1) {
            var t: usize = 0;
            while (t < seq) : (t += 1) {
                var i: usize = 0;
                while (i < d) : (i += 1) {
                    const idx = [_]usize{b, t, i};
                    const c_val = conv_out.get(&idx);
                    const m_val = mem_out.get(&idx);
                    const x_val = input.get(&idx);

                    var gate_logit: f32 = 0;
                    var j: usize = 0;
                    while (j < d) : (j += 1) {
                        const g_idx1 = [_]usize{j, i};
                        const g_idx2 = [_]usize{j + d, i};
                        const in_j = input.get(&[_]usize{b, t, j});
                        gate_logit += in_j * self.gate_w.get(&g_idx1); 
                    }

                    const z = self.sigmoid(gate_logit);
                    const h = z * c_val + (1.0 - z) * m_val;

                    const final = self.silu(h * self.norm.get(&[_]usize{i})) + x_val;
                    output.set(&idx, final);
                }
            }
        }
    }
};

pub const RGAMModel = struct {
    layers: []RGAMLayer,
    allocator: Allocator,
    config: Config,

    pub fn init(allocator: Allocator, config: Config) !RGAMModel {
        const layers = try allocator.alloc(RGAMLayer, config.depth);
        var i: usize = 0;
        while (i < config.depth) : (i += 1) {
            layers[i] = try RGAMLayer.init(allocator, config);
        }
        return RGAMModel{
            .layers = layers,
            .allocator = allocator,
            .config = config,
        };
    }

    pub fn deinit(self: *RGAMModel) void {
        for (self.layers) |*l| l.deinit();
        self.allocator.free(self.layers);
    }

    pub fn forward(self: *RGAMModel, input: Tensor) !Tensor {
        var current = try Tensor.init(self.allocator, input.shape);
        @memcpy(current.data, input.data);

        for (self.layers) |*layer| {
            var next = try Tensor.init(self.allocator, current.shape);
            try layer.forward(current, &next);
            current.deinit();
            current = next;
        }
        return current;
    }
};

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    const allocator = gpa.allocator();

    const config = Config{
        .dim = 64,
        .depth = 2,
        .head_dim = 16,
        .heads = 4,
        .vocab_size = 1000,
        .context_limit = 50000000,
    };

    var model = try RGAMModel.init(allocator, config);
    defer model.deinit();

    const input_shape = [_]usize{1, 128, 64};
    var input = try Tensor.init(allocator, &input_shape);
    defer input.deinit();

    var prng = std.rand.DefaultPrng.init(999);
    const random = prng.random();
    for (input.data) |*x| x.* = random.float(f32);

    var output = try model.forward(input);
    defer output.deinit();

    const out_idx = [_]usize{0, 0, 0};
    std.debug.print("RGAM Output[0,0,0]: {d}\n", .{output.get(&out_idx)});
}
