    allocator: std.mem.Allocator,
    weights_real: Tensor,
    weights_imag: Tensor,
    scale: f32,

    pub fn init(allocator: std.mem.Allocator, dim: usize) TensorError!ResonanceMemory {
        const shape_rows = dim;
        const shape_cols = dim;
        var w_real = try Tensor.init(allocator, shape_rows, shape_cols);
        var w_imag = try Tensor.init(allocator, shape_rows, shape_cols);

        var prng = std.rand.DefaultPrng.init(42);
        const random = prng.random();

        var i: usize = 0;
        while (i < w_real.data.len) : (i += 1) {
            w_real.data[i] = (random.float(f32) - 0.5) * 0.02;
        }
        i = 0;
        while (i < w_imag.data.len) : (i += 1) {
            w_imag.data[i] = (random.float(f32) - 0.5) * 0.02;
        }

        return ResonanceMemory{
            .dim = dim,
            .allocator = allocator,
            .weights_real = w_real,
            .weights_imag = w_imag,
            .scale = 1.0 / @sqrt(@as(f32, @floatFromInt(dim))),
        };
    }

    pub fn deinit(self: *ResonanceMemory) void {
        self.weights_real.deinit();
        self.weights_imag.deinit();
    }

    pub fn forward(self: *ResonanceMemory, input: []const f32, seq: usize, dim: usize, output: []f32) void {
        var t: usize = 0;
        while (t < seq) : (t += 1) {
            var i: usize = 0;
            while (i < dim) : (i += 1) {
                var sum_r: f32 = 0;
                var j: usize = 0;
                while (j < dim) : (j += 1) {
                    const val = input[t * dim + j];
                    const wr = self.weights_real.get(i, j);
                    const wi = self.weights_imag.get(i, j);
                    const phase = val * self.scale;
                    const cos_p = @cos(phase);
                    const sin_p = @sin(phase);
                    const rot_r = cos_p * wr - sin_p * wi;
                    sum_r += rot_r;
                    j += 1;
                }
                output[t * dim + i] = sum_r;
            }
        }
    }
};

pub const CausalConv1D = struct {
    allocator: std.mem.Allocator,
    kernel: Tensor,
    kernel_size: usize,
    dim: usize,

    pub fn init(allocator: std.mem.Allocator, dim: usize, kernel_size: usize) TensorError!CausalConv1D {
        var k = try Tensor.init(allocator, dim, kernel_size);

        var prng = std.rand.DefaultPrng.init(123);
        const random = prng.random();

        var i: usize = 0;
        while (i < k.data.len) : (i += 1) {
            k.data[i] = (random.float(f32) - 0.5) * 0.1;
        }

        return CausalConv1D{
            .allocator = allocator,
            .kernel = k,
            .kernel_size = kernel_size,
            .dim = dim,
        };
    }

    pub fn deinit(self: *CausalConv1D) void {
        self.kernel.deinit();
    }

    pub fn forward(self: *CausalConv1D, input: []const f32, seq: usize, dim: usize, output: []f32) void {
        var t: usize = 0;
        while (t < seq) : (t += 1) {
            var c: usize = 0;
            while (c < dim) : (c += 1) {
                var sum: f32 = 0;
                var k_i: usize = 0;
                while (k_i < self.kernel_size) : (k_i += 1) {
                    if (t >= k_i) {
                        const in_val = input[(t - k_i) * dim + c];
                        const k_val = self.kernel.get(c, k_i);
                        sum += in_val * k_val;
                    }
                }
                output[t * dim + c] = sum;
            }
        }
    }
};

pub const RGAMLayer = struct {
    allocator: std.mem.Allocator,
    dim: usize,
    conv: CausalConv1D,
    memory: ResonanceMemory,
    gate_w: Tensor,
    norm_scale: []f32,

    pub fn init(allocator: std.mem.Allocator, config: RGAMConfig) TensorError!RGAMLayer {
        const conv = try CausalConv1D.init(allocator, config.dim, 4);
        const memory = try ResonanceMemory.init(allocator, config.dim);
        var gw = try Tensor.init(allocator, config.dim * 2, config.dim);
        const norm_scale = try allocator.alloc(f32, config.dim);

        var prng = std.rand.DefaultPrng.init(777);
        const random = prng.random();

        var i: usize = 0;
        while (i < gw.data.len) : (i += 1) {
            gw.data[i] = (random.float(f32) - 0.5) * 0.02;
        }

        i = 0;
        while (i < config.dim) : (i += 1) {
            norm_scale[i] = 1.0;
            i += 1;
        }

        return RGAMLayer{
            .allocator = allocator,
            .dim = config.dim,
            .conv = conv,
            .memory = memory,
            .gate_w = gw,
            .norm_scale = norm_scale,
        };
    }

    pub fn deinit(self: *RGAMLayer) void {
        self.conv.deinit();
        self.memory.deinit();
        self.gate_w.deinit();
        if (self.norm_scale.len != 0) {
            self.allocator.free(self.norm_scale);
        }
    }

    fn silu(x: f32) f32 {
        return x / (1.0 + @exp(-x));
    }

    fn sigmoid(x: f32) f32 {
        return 1.0 / (1.0 + @exp(-x));
    }

    fn layer_norm(self: *RGAMLayer, x: []f32, seq: usize, dim: usize) void {
        var t: usize = 0;
        while (t < seq) : (t += 1) {
            var mean: f32 = 0;
            var i: usize = 0;
            while (i < dim) : (i += 1) {
                mean += x[t * dim + i];
            }
            mean /= @as(f32, @floatFromInt(dim));

            var var_acc: f32 = 0;
            i = 0;
            while (i < dim) : (i += 1) {
                const diff = x[t * dim + i] - mean;
                var_acc += diff * diff;
            }
            var_acc /= @as(f32, @floatFromInt(dim));
            const eps: f32 = 1e-5;
            const inv_std = 1.0 / @sqrt(var_acc + eps);

            i = 0;
            while (i < dim) : (i += 1) {
                const normed = (x[t * dim + i] - mean) * inv_std;
                x[t * dim + i] = normed * self.norm_scale[i];
            }
        }
    }

    pub fn forward(self: *RGAMLayer, input: []const f32, seq: usize, dim: usize, output: []f32) TensorError!void {
        if (dim != self.dim) return TensorError.InvalidVectorLength;

        var tmp = try self.allocator.alloc(f32, seq * dim);
        defer self.allocator.free(tmp);

        var i: usize = 0;
        while (i < seq * dim) : (i += 1) {
            tmp[i] = input[i];
        }
        self.layer_norm(tmp, seq, dim);

        var conv_out = try self.allocator.alloc(f32, seq * dim);
        defer self.allocator.free(conv_out);
        self.conv.forward(tmp, seq, dim, conv_out);

        var mem_out = try self.allocator.alloc(f32, seq * dim);
        defer self.allocator.free(mem_out);
        self.memory.forward(tmp, seq, dim, mem_out);

        var t: usize = 0;
        while (t < seq) : (t += 1) {
            var i_d: usize = 0;
            while (i_d < dim) : (i_d += 1) {
                var gate_logit: f32 = 0;
                var j: usize = 0;
                while (j < dim) : (j += 1) {
                    const in_val = tmp[t * dim + j];
                    const g_val = self.gate_w.get(j, i_d);
                    gate_logit += in_val * g_val;
                }
                const z = sigmoid(gate_logit);
                const c_val = conv_out[t * dim + i_d];
                const m_val = mem_out[t * dim + i_d];
                const mixed = z * c_val + (1.0 - z) * m_val;
                const residual = tmp[t * dim + i_d];
                const final_val = silu(mixed) + residual;
                output[t * dim + i_d] = final_val;
            }
        }
    }
};

pub const RGAMModel = struct {
    layers: []RGAMLayer,
    allocator: std.mem.Allocator,
    config: RGAMConfig,

    pub fn init(allocator: std.mem.Allocator, config: RGAMConfig) TensorError!RGAMModel {
        if (config.dim == 0 or config.depth == 0) return TensorError.InvalidConfig;
        const layers = try allocator.alloc(RGAMLayer, config.depth);
        var i: usize = 0;
        while (i < config.depth) : (i += 1) {
            layers[i] = try RGAMLayer.init(allocator, config);
        }
        return RGAMModel{
            .layers = layers,
            .allocator = allocator,
            .config = config,
        };
    }

    pub fn deinit(self: *RGAMModel) void {
        for (self.layers) |*l| {
            l.deinit();
        }
        if (self.layers.len != 0) {
            self.allocator.free(self.layers);
        }
    }

    pub fn forward(self: *RGAMModel, input: []const f32, seq: usize) TensorError![]f32 {
        const dim = self.config.dim;
        var current = try self.allocator.alloc(f32, seq * dim);
        var i: usize = 0;
        while (i < seq * dim) : (i += 1) {
            current[i] = input[i];
        }

        var layer_index: usize = 0;
        while (layer_index < self.config.depth) : (layer_index += 1) {
            var next = try self.allocator.alloc(f32, seq * dim);
            try self.layers[layer_index].forward(current, seq, dim, next);
            self.allocator.free(current);
            current = next;
        }
        return current;
    }
};

