const std = @import("std");

pub const AHNConfig = struct {
    dim: usize,
    head_dim: usize,
    window_size: usize,
    batch_size: usize,
};

pub const Tensor = struct {
    data: []f32,
    rows: usize,
    cols: usize,
    allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator, rows: usize, cols: usize) !Tensor {
        if (rows == 0 or cols == 0) return error.InvalidTensorShape;
        const data = try allocator.alloc(f32, rows * cols);
        @memset(data, 0);
        return Tensor{
            .data = data,
            .rows = rows,
            .cols = cols,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *Tensor) void {
        if (self.data.len != 0) {
            self.allocator.free(self.data);
        }
        self.data = &[_]f32{};
        self.rows = 0;
        self.cols = 0;
    }

    pub fn get(self: *const Tensor, r: usize, c: usize) f32 {
        return self.data[r * self.cols + c];
    }

    pub fn set(self: *Tensor, r: usize, c: usize, val: f32) void {
        self.data[r * self.cols + c] = val;
    }

    pub fn rowSlice(self: *Tensor, r: usize) []f32 {
        const start = r * self.cols;
        return self.data[start .. start + self.cols];
    }

    pub fn rowSliceConst(self: *const Tensor, r: usize) []const f32 {
        const start = r * self.cols;
        return self.data[start .. start + self.cols];
    }
};

pub const GatedDeltaCompressor = struct {
    state: Tensor,
    config: AHNConfig,
    allocator: std.mem.Allocator,
    beta: f32,
    alpha: f32,

    pub fn init(allocator: std.mem.Allocator, config: AHNConfig, beta: f32, alpha: f32) !GatedDeltaCompressor {
        const state = try Tensor.init(allocator, config.dim, config.dim);
        return GatedDeltaCompressor{
            .state = state,
            .config = config,
            .allocator = allocator,
            .beta = beta,
            .alpha = alpha,
        };
    }

    pub fn deinit(self: *GatedDeltaCompressor) void {
        self.state.deinit();
    }

    pub fn compress_step(self: *GatedDeltaCompressor, k: []const f32, v: []const f32) void {
        var i: usize = 0;
        while (i < self.config.dim) : (i += 1) {
            var j: usize = 0;
            const vi = v[i];
            while (j < self.config.dim) : (j += 1) {
                const current_s = self.state.get(i, j);
                const update = self.beta * (vi * k[j]);
                const new_val = (self.alpha * current_s) + update;
                self.state.set(i, j, new_val);
            }
        }
    }

    pub fn project(self: *GatedDeltaCompressor, q: []const f32, out: []f32) void {
        var i: usize = 0;
        while (i < self.config.dim) : (i += 1) {
            var acc: f32 = 0;
            var j: usize = 0;
            while (j < self.config.dim) : (j += 1) {
                acc += self.state.get(i, j) * q[j];
            }
            out[i] += acc;
        }
    }
};

pub const ArtificialHippocampus = struct {
    compressor: GatedDeltaCompressor,
    window_k: Tensor,
    window_v: Tensor,
    current_pos: usize,
    config: AHNConfig,
    allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator, config: AHNConfig) !ArtificialHippocampus {
        if (config.dim == 0 or config.window_size == 0) return error.InvalidConfig;
        const compressor = try GatedDeltaCompressor.init(allocator, config, 0.1, 0.99);
        const window_k = try Tensor.init(allocator, config.window_size, config.dim);
        const window_v = try Tensor.init(allocator, config.window_size, config.dim);

        return ArtificialHippocampus{
            .compressor = compressor,
            .window_k = window_k,
            .window_v = window_v,
            .current_pos = 0,
            .config = config,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *ArtificialHippocampus) void {
        self.compressor.deinit();
        self.window_k.deinit();
        self.window_v.deinit();
        self.current_pos = 0;
    }

    fn computeAttentionScores(self: *ArtificialHippocampus, q_in: []const f32, active_window: usize, scores: []f32) void {
        var w: usize = 0;
        while (w < active_window) : (w += 1) {
            var dot: f32 = 0;
            var j: usize = 0;
            const row_k = self.window_k.rowSliceConst(w);
            while (j < self.config.dim) : (j += 1) {
                dot += q_in[j] * row_k[j];
            }
            scores[w] = dot;
        }
        var max_score: f32 = scores[0];
        w = 1;
        while (w < active_window) : (w += 1) {
            if (scores[w] > max_score) {
                max_score = scores[w];
            }
        }
        var sum_exp: f32 = 0;
        w = 0;
        while (w < active_window) : (w += 1) {
            scores[w] = @exp(scores[w] - max_score);
            sum_exp += scores[w];
        }
        if (sum_exp == 0) {
            const inv = 1.0 / @as(f32, @floatFromInt(active_window));
            w = 0;
            while (w < active_window) : (w += 1) {
                scores[w] = inv;
            }
        } else {
            w = 0;
            while (w < active_window) : (w += 1) {
                scores[w] /= sum_exp;
            }
        }
    }

    pub fn forward_token(self: *ArtificialHippocampus, k_in: []const f32, v_in: []const f32, q_in: []const f32) ![]f32 {
        if (k_in.len != self.config.dim or v_in.len != self.config.dim or q_in.len != self.config.dim) {
            return error.InvalidVectorLength;
        }

        if (self.current_pos >= self.config.window_size) {
            const oldest_idx = self.current_pos % self.config.window_size;
            const k_old = self.window_k.rowSliceConst(oldest_idx);
            const v_old = self.window_v.rowSliceConst(oldest_idx);
            self.compressor.compress_step(k_old, v_old);
        }

        const write_idx = self.current_pos % self.config.window_size;
        var d: usize = 0;
        var row_k = self.window_k.rowSlice(write_idx);
        var row_v = self.window_v.rowSlice(write_idx);
        while (d < self.config.dim) : (d += 1) {
            row_k[d] = k_in[d];
            row_v[d] = v_in[d];
        }

        const output = try self.allocator.alloc(f32, self.config.dim);
        @memset(output, 0);

        self.compressor.project(q_in, output);

        const active_window = if (self.current_pos + 1 < self.config.window_size) self.current_pos + 1 else self.config.window_size;
        const attn_scores = try self.allocator.alloc(f32, active_window);
        defer self.allocator.free(attn_scores);

        self.computeAttentionScores(q_in, active_window, attn_scores);

        var w: usize = 0;
        while (w < active_window) : (w += 1) {
            const attn_score = attn_scores[w];
            const row_v_const = self.window_v.rowSliceConst(w);
            var i: usize = 0;
            while (i < self.config.dim) : (i += 1) {
                output[i] += attn_score * row_v_const[i];
            }
        }

        self.current_pos += 1;
        return output;
    }
};

fn initVector(allocator: std.mem.Allocator, len: usize, value: f32) ![]f32 {
    const v = try allocator.alloc(f32, len);
    var i: usize = 0;
    while (i < len) : (i += 1) {
        v[i] = value;
    }
    return v;
}

