    const k_dummy = try initVector(allocator, config.dim, 0.5);
    const v_dummy = try initVector(allocator, config.dim, 0.1);
    const q_dummy = try initVector(allocator, config.dim, 0.2);
    defer allocator.free(k_dummy);
    defer allocator.free(v_dummy);
    defer allocator.free(q_dummy);

    var step: usize = 0;
    while (step < 200) : (step += 1) {
        const out = try ahn.forward_token(k_dummy, v_dummy, q_dummy);
        allocator.free(out);
    }

    const stdout = std.io.getStdOut().writer();
    try stdout.print("AHN processing completed: {d} steps\n", .{200});
}
