pub const JaideError = error{
    OutOfMemory,
    InvalidInput,
    MathOverflow,
    AllocFail,
    NetworkError,
    JsonParseError,
    FileError,
    ThreadError,
    QuantumError,
    ZkProofError,
};

const F = FLOAT_TYPE;
const I = INT_TYPE;

fn DynamicTensor(comptime T: type, comptime Dims: [3]usize) type {
    return struct {
        data: []T,
        shape: [3]usize = Dims,
        allocator: mem.Allocator,

        fn init(allocator: mem.Allocator) JaideError!@This() {
            const total_size: usize = Dims[0] * Dims[1] * Dims[2];
            const data = try allocator.alloc(T, total_size);
            errdefer allocator.free(data);
            @memset(data, 0);
            return .{ .data = data, .allocator = allocator };
        }

        fn deinit(self: *@This()) void {
            self.allocator.free(self.data);
            self.* = undefined;
        }

        fn get(self: *const @This(), idx0: usize, idx1: usize, idx2: usize) T {
            return self.data[idx0 * (self.shape[1] * self.shape[2]) + idx1 * self.shape[2] + idx2];
        }

        fn set(self: *@This(), idx0: usize, idx1: usize, idx2: usize, value: T) void {
            self.data[idx0 * (self.shape[1] * self.shape[2]) + idx1 * self.shape[2] + idx2] = value;
        }

        fn add(self: *@This(), other: *const @This()) JaideError!void {
            if (self.shape[0] != other.shape[0] or self.shape[1] != other.shape[1] or self.shape[2] != other.shape[2]) return JaideError.InvalidInput;
            const total_size = self.shape[0] * self.shape[1] * self.shape[2];
            for (0..total_size) |i| {
                self.data[i] += other.data[i];
            }
        }

        fn scale(self: *@This(), factor: F) void {
            const total_size = self.shape[0] * self.shape[1] * self.shape[2];
            for (0..total_size) |i| {
                self.data[i] *= factor;
            }
        }

        fn matmul(self: *const @This(), other: *const @This(), result: *@This()) JaideError!void {
            if (self.shape[1] != other.shape[0] or self.shape[0] != result.shape[0] or other.shape[1] != result.shape[1]) return JaideError.InvalidInput;
            for (0..result.shape[0]) |i| {
                for (0..result.shape[1]) |j| {
                    var sum: F = 0;
                    for (0..self.shape[1]) |k| {
                        sum += self.get(i, k, 0) * other.get(k, j, 0);
                    }
                    result.set(i, j, 0, sum);
                }
            }
        }
    };
}

const Neuron = struct {
    potential: F,
    conductance: F,
    refractory: bool,
    synapses: ArrayList(usize),
    weights: []F,

    fn init(allocator: mem.Allocator, num_synapses: usize) JaideError!@This() {
        var self = @This(){
            .potential = 0.0,
            .conductance = 0.0,
            .refractory = false,
            .synapses = ArrayList(usize).init(allocator),
            .weights = try allocator.alloc(F, num_synapses),
        };
        errdefer {
            self.synapses.deinit();
            allocator.free(self.weights);
        }
        @memset(self.weights, 0.0);
        return self;
    }

    fn deinit(self: *@This(), allocator: mem.Allocator) void {
        self.synapses.deinit();
        allocator.free(self.weights);
        self.* = undefined;
    }

    fn update(self: *@This(), input: []const F, dt: F) void {
        if (self.refractory) {
            self.potential *= math.exp(-self.conductance * dt);
            if (self.potential < 0.01) {
                self.refractory = false;
            }
            return;
        }
        var spike_sum: F = 0;
        for (0..self.synapses.items.len) |i| {
            if (self.synapses.items[i] < input.len) {
                spike_sum += input[self.synapses.items[i]] * self.weights[i];
            }
        }
        self.potential += spike_sum - self.potential * self.conductance * dt;
        if (self.potential > POTENTIAL_BOUND) {
            self.potential = 0;
            self.refractory = true;
            self.conductance = 0.1;
        }
    }

    fn hebbianUpdate(self: *@This(), pre_spike: bool, post_spike: bool, eta: F) void {
        if (pre_spike and post_spike) {
            for (0..self.weights.len) |i| {
                self.weights[i] += eta * 0.01;
                if (self.weights[i] > 1.0) self.weights[i] = 1.0;
            }
        } else if (pre_spike and !post_spike) {
            for (0..self.weights.len) |i| {
                self.weights[i] -= eta * 0.01;
                if (self.weights[i] < -1.0) self.weights[i] = -1.0;
            }
        }
    }
};

const DiffusiveMemristorLayer = struct {
    neurons: []Neuron,
    num_neurons: usize,
    diffusion_coeff: F,
    dt: F,
    allocator: mem.Allocator,

    fn init(allocator: mem.Allocator, num_neurons: usize, diffusion_coeff: F, dt: F) JaideError!@This() {
        var self = @This{}{
            .neurons = try allocator.alloc(Neuron, num_neurons),
            .num_neurons = num_neurons,
            .diffusion_coeff = diffusion_coeff,
            .dt = dt,
            .allocator = allocator,
        };
        errdefer allocator.free(self.neurons);
        for (0..num_neurons) |i| {
            self.neurons[i] = try Neuron.init(allocator, num_neurons);
        }
        errdefer for (0..num_neurons) |j| {
            self.neurons[j].deinit(allocator);
        };
        return self;
    }

    fn deinit(self: *@This()) void {
        for (self.neurons) |*n| {
            n.deinit(self.allocator);
        }
        self.allocator.free(self.neurons);
        self.* = undefined;
    }

    fn forward(self: *@This(), input: []const F, output: []F) JaideError!void {
        if (input.len < self.num_neurons or output.len < self.num_neurons) return JaideError.InvalidInput;
        var spikes = try self.allocator.alloc(bool, self.num_neurons);
        errdefer self.allocator.free(spikes);
        @memset(spikes, false);
        for (0..self.num_neurons) |i| {
            self.neurons[i].update(input, self.dt);
            if (self.neurons[i].potential > 1.0) {
                spikes[i] = true;
                output[i] = 1.0;
            } else {
                output[i] = 0.0;
            }
        }
        for (0..self.num_neurons) |i| {
            if (spikes[i]) {
                self.neurons[i].hebbianUpdate(true, true, 0.1);
                for (0..self.num_neurons) |j| {
                    if (i != j) {
                        self.neurons[j].hebbianUpdate(spikes[i], spikes[j], 0.01);
                    }
                }
            }
        }
        self.allocator.free(spikes);
        self.diffusePotentials();
    }

    fn diffusePotentials(self: *@This()) void {
        for (0..self.num_neurons) |i| {
            var diffusion: F = 0;
            for (0..self.num_neurons) |j| {
                if (i != j) {
                    const diff = self.neurons[i].potential - self.neurons[j].potential;
                    diffusion += self.diffusion_coeff * diff * self.dt;
                }
            }
            self.neurons[i].potential += diffusion / @as(F, @floatFromInt(self.num_neurons - 1));
            if (self.neurons[i].potential < 0 or self.neurons[i].potential > POTENTIAL_BOUND) {
                self.neurons[i].potential = math.clamp(self.neurons[i].potential, 0.0, POTENTIAL_BOUND);
            }
        }
    }
};

const QuantumNoiseInjector = struct {
    qubits: usize,
    t1: F,
    t2: F,
    state: []F,
    allocator: mem.Allocator,

    fn init(allocator: mem.Allocator, qubits: usize, t1: F, t2: F) JaideError!@This() {
        var self = @This{}{
            .qubits = qubits,
            .t1 = t1,
            .t2 = t2,
            .state = try allocator.alloc(F, qubits * 2),
            .allocator = allocator,
        };
        errdefer allocator.free(self.state);
        var prng = Rng.init(42);
        var rng = prng.random();
        for (0..qubits * 2) |i| {
            self.state[i] = rng.float(F);
        }
        return self;
    }

    fn deinit(self: *@This()) void {
        self.allocator.free(self.state);
        self.* = undefined;
    }

    fn injectNoise(self: *@This(), signal: []F) JaideError!void {
        if (signal.len != self.qubits) return JaideError.InvalidInput;
        var decay = math.exp(-self.dt / self.t1);
        var dephase = math.exp(-self.dt / self.t2);
        for (0..self.qubits) |q| {
            const real_idx = q * 2;
            const imag_idx = q * 2 + 1;
            const magnitude = math.sqrt(self.state[real_idx] * self.state[real_idx] + self.state[imag_idx] * self.state[imag_idx]);
            if (magnitude > 0) {
                const noise_real = self.state[real_idx] * decay * dephase * (rng.float(F) - 0.5);
                const noise_imag = self.state[imag_idx] * decay * (1 - dephase) * (rng.float(F) - 0.5);
                signal[q] += noise_real;
            }
        }
    }
};

const AstrologicalModulator = struct {
    knots: usize,
    positions: []F,
    spline_coeffs: []F,
    allocator: mem.Allocator,

    fn init(allocator: mem.Allocator, knots: usize) JaideError!@This() {
        var self = @This{}{
            .knots = knots,
            .positions = try allocator.alloc(F, knots),
            .spline_coeffs = try allocator.alloc(F, knots * 4),
            .allocator = allocator,
        };
        errdefer {
            allocator.free(self.positions);
            allocator.free(self.spline_coeffs);
        }
        for (0..knots) |i| {
            self.positions[i] = @as(F, @floatFromInt(i)) * 2.0 / @as(F, @floatFromInt(knots - 1));
        }
        var prng = Rng.init(123);
        var rng = prng.random();
        for (0..knots * 4) |j| {
            self.spline_coeffs[j] = rng.float(F) * CONDUCTANCE_RANGE;
        }
        return self;
    }

    fn deinit(self: *@This()) void {
        self.allocator.free(self.positions);
        self.allocator.free(self.spline_coeffs);
        self.* = undefined;
    }

    fn modulate(self: *@This(), input: []F, time_step: F) void {
        const normalized_time = math.mod(F, time_step, 2.0 * math.pi) / (2.0 * math.pi);
        for (0..input.len) |i| {
            var knot_influence: F = 0;
            for (0..self.knots) |k| {
                const dist = math.abs(normalized_time - self.positions[k]);
                const basis = if (dist < 0.5) 1.0 - 2.0 * dist * dist else 0;
                knot_influence += basis * self.spline_coeffs[k % (self.knots * 4)];
            }
            input[i] *= math.clamp(knot_influence, 0.0, CONDUCTANCE_RANGE);
        }
    }
};

const RSFProcessor = struct {
    layers: []DiffusiveMemristorLayer,
    quantum_injector: QuantumNoiseInjector,
    astro_modulator: AstrologicalModulator,
    num_layers: usize,
    allocator: mem.Allocator,

    fn init(allocator: mem.Allocator, num_layers: usize, neurons_per_layer: usize, qubits: usize) JaideError!@This() {
        var self = @This{}{
            .layers = try allocator.alloc(DiffusiveMemristorLayer, num_layers),
            .num_layers = num_layers,
            .allocator = allocator,
            .quantum_injector = undefined,
            .astro_modulator = undefined,
        };
        errdefer allocator.free(self.layers);
        self.quantum_injector = try QuantumNoiseInjector.init(allocator, qubits, 1000.0, 2000.0);
        self.astro_modulator = try AstrologicalModulator.init(allocator, ASTRO_KNOTS);
        errdefer {
            self.quantum_injector.deinit();
            self.astro_modulator.deinit();
        }
        for (0..num_layers) |l| {
            self.layers[l] = try DiffusiveMemristorLayer.init(allocator, neurons_per_layer, 0.1, 0.01);
        }
        errdefer for (0..num_layers) |ll| {
            self.layers[ll].deinit();
        };
        return self;
    }

    fn deinit(self: *@This()) void {
        self.quantum_injector.deinit();
        self.astro_modulator.deinit();
        for (self.layers) |*l| {
            l.deinit();
        }
        self.allocator.free(self.layers);
        self.* = undefined;
    }

    fn process(self: *@This(), input: []const F, output: []F, seq_len: usize) JaideError!void {
        if (input.len != seq_len * self.layers[0].num_neurons or output.len != seq_len * self.layers[0].num_neurons) return JaideError.InvalidInput;
        if (seq_len > MAX_SEQ_LEN) return JaideError.InvalidInput;
        var current = try self.allocator.alloc(F, input.len);
        errdefer self.allocator.free(current);
        @memcpy(current, input);
        var time_step: F = 0;
        for (0..self.num_layers) |l| {
            self.astro_modulator.modulate(current, time_step);
            time_step += 1.0;
            var layer_out = try self.allocator.alloc(F, seq_len * self.layers[l].num_neurons);
            errdefer self.allocator.free(layer_out);
            try self.layers[l].forward(current, layer_out);
            self.allocator.free(current);
            current = layer_out;
            if (l % 2 == 0) {
                try self.quantum_injector.injectNoise(current);
            }
            for (0..seq_len * self.layers[l].num_neurons) |i| {
                if (current[i] > DIFFUSION_THRESHOLD) {
                    current[i] = 1.0;
                } else {
                    current[i] = 0.0;
                }
            }
        }
        @memcpy(output, current);
        self.allocator.free(current);
    }
};

const Node = struct {
    id: usize,
    anchors: []usize,
    children: ArrayList(usize),
    depth: usize,
    relevance_score: F,
    allocator: mem.Allocator,

    fn init(allocator: mem.Allocator, id: usize, depth: usize) JaideError!@This() {
        var self = @This{}{
            .id = id,
            .anchors = &.{},
            .children = ArrayList(usize).init(allocator),
            .depth = depth,
            .relevance_score = 0.0,
            .allocator = allocator,
        };
        return self;
    }

    fn deinit(self: *@This()) void {
        self.children.deinit();
        if (self.anchors.len > 0) self.allocator.free(self.anchors);
        self.* = undefined;
    }

    fn addAnchor(self: *@This(), anchor_idx: usize) JaideError!void {
        if (self.anchors.len == 0) {
            self.anchors = try self.allocator.alloc(usize, 1);
        } else {
            const new_len = self.anchors.len + 1;
            const new_anchors = try self.allocator.realloc(usize, self.anchors, new_len);
            self.anchors = new_anchors;
        }
        self.anchors[self.anchors.len - 1] = anchor_idx;
    }

    fn computeRelevance(self: *@This(), query_tokens: []const usize) F {
        var score: F = 0;
        for (self.anchors) |anchor| {
            if (anchor < query_tokens.len) {
                score += 1.0 / (@as(F, @floatFromInt(self.depth + 1)) + math.abs(@as(F, @floatFromInt(anchor - query_tokens.len / 2))));
            }
        }
        self.relevance_score = score;
        return score;
    }
};

const SSIIndex = struct {
    root: Node,
    leaves: []Node,
    max_depth: usize,
    total_tokens: usize,
    allocator: mem.Allocator,

    fn init(allocator: mem.Allocator, max_depth: usize) JaideError!@This() {
        var self = @This{}{
            .root = try Node.init(allocator, 0, 0),
            .leaves = &.{},
            .max_depth = max_depth,
            .total_tokens = 0,
            .allocator = allocator,
        };
        self.buildTree();
        return self;
    }

    fn deinit(self: *@This()) void {
        self.root.deinit();
        for (self.leaves) |*leaf| {
            leaf.deinit();
        }
        self.allocator.free(self.leaves);
        self.* = undefined;
    }

    fn buildTree(self: *@This()) void {
        var current_nodes = ArrayList(usize).init(self.allocator);
        defer current_nodes.deinit();
        try current_nodes.append(0);
        var current_depth: usize = 0;
        var node_id: usize = 1;
        while (current_depth < self.max_depth) : (current_depth += 1) {
            var next_nodes = ArrayList(usize).init(self.allocator);
            defer next_nodes.deinit();
            for (current_nodes.items) |parent_id| {
                var children = [_]usize{ node_id, node_id + 1 };
                node_id += 2;
                for (children) |child_id| {
                    try self.root.children.append(child_id); // Simplified, assume root has all
                    try next_nodes.append(child_id);
                }
            }
            current_nodes = next_nodes;
        }
        self.leaves = try self.allocator.alloc(Node, current_nodes.items.len);
        for (0..current_nodes.items.len) |i| {
            self.leaves[i] = try Node.init(self.allocator, current_nodes.items[i], self.max_depth);
        }
    }

    fn insertTokens(self: *@This(), tokens: []const usize) JaideError!void {
        if (tokens.len > MAX_SEQ_LEN) return JaideError.InvalidInput;
        self.total_tokens += tokens.len;
        const leaf_idx = math.clamp(tokens.len % self.leaves.len, 0, self.leaves.len - 1);
        try self.leaves[leaf_idx].addAnchor(tokens.len / 2);
        for (0..self.max_depth) |d| {
            const node = &self.root; // Traverse simplified
            node.computeRelevance(tokens);
        }
    }

    fn retrieveTopK(self: *@This(), query_tokens: []const usize, k: usize) JaideError![]usize {
        var scores = ArrayList(struct { idx: usize, score: F }).init(self.allocator);
        defer scores.deinit();
        for (0..self.leaves.len) |i| {
            const score = self.leaves[i].computeRelevance(query_tokens);
            try scores.append(.{ .idx = i, .score = score });
        }
        std.sort.sort(struct { idx: usize, score: F }, scores.items, {}, comptime struct {
            fn less(a: struct { idx: usize, score: F }, b: struct { idx: usize, score: F }) bool {
                return a.score > b.score;
            }
        }.less);
        var top_k = try self.allocator.alloc(usize, math.min(k, scores.items.len));
        for (0..top_k.len) |i| {
            top_k[i] = scores.items[i].idx;
        }
        return top_k;
    }
};

const Ranker = struct {
    lsh_tables: []AutoHashMap(usize, ArrayList(usize)),
    num_tables: usize,
    num_buckets: usize,
    allocator: mem.Allocator,

    fn init(allocator: mem.Allocator, num_tables: usize, num_buckets: usize) JaideError!@This() {
        var self = @This{}{
            .lsh_tables = try allocator.alloc(AutoHashMap(usize, ArrayList(usize)), num_tables),
            .num_tables = num_tables,
            .num_buckets = num_buckets,
            .allocator = allocator,
        };
        errdefer allocator.free(self.lsh_tables);
        for (0..num_tables) |t| {
            self.lsh_tables[t] = AutoHashMap(usize, ArrayList(usize)).init(allocator);
        }
        return self;
    }

    fn deinit(self: *@This()) void {
        for (self.lsh_tables) |*table| {
            var it = table.iterator();
            while (it.next()) |entry| {
                entry.value_ptr.deinit();
            }
            table.deinit();
        }
        self.allocator.free(self.lsh_tables);
        self.* = undefined;
    }

    fn hashNgram(self: *@This(), ngram: []const usize, table_idx: usize) usize {
        var hash_val: usize = 0;
        for (ngram) |token| {
            hash_val = hash_val * 31 + @as(usize, @intFromFloat(@round(@as(f64, @floatCast(token)) * 1e6)));
        }
        return hash_val % self.num_buckets;
    }

    fn addNgrams(self: *@This(), tokens: []const usize, doc_id: usize) JaideError!void {
        const n = 3;
        for (0..tokens.len - n + 1) |start| {
            var ngram = tokens[start..start + n];
            for (0..self.num_tables) |t| {
                const bucket = self.hashNgram(ngram, t);
                if (!self.lsh_tables[t].contains(bucket)) {
                    var list = ArrayList(usize).init(self.allocator);
                    try self.lsh_tables[t].put(bucket, list);
                }
                try self.lsh_tables[t].getPtr(bucket).?.append(doc_id);
            }
        }
    }

    fn rankCandidates(self: *@This(), query_ngrams: [][]const usize, candidates: []usize) []usize {
        var scores = try self.allocator.alloc(F, candidates.len);
        defer self.allocator.free(scores);
        @memset(scores, 0);
        for (0..candidates.len) |c| {
            for (query_ngrams) |q_ngram| {
                for (0..self.num_tables) |t| {
                    const bucket = self.hashNgram(q_ngram, t);
                    if (self.lsh_tables[t].get(bucket)) |list| {
                        for (list.items) |doc| {
                            if (doc == candidates[c]) {
                                scores[c] += 1.0 / @as(F, @floatFromInt(list.items.len));
                            }
                        }
                    }
                }
            }
        }
        var ranked = try self.allocator.alloc(usize, candidates.len);
        for (0..candidates.len) |i| {
            ranked[i] = i;
        }
        std.sort.sort(usize, ranked, scores, struct {
            fn less(a: []const F, b: usize, c: usize) bool {
                return a[b] > a[c];
            }
        }.less);
        return ranked;
    }
};

const MGTTokens = struct {
    vocab: []const u8,
    vocab_size: usize,
    inverse_vocab: HashMap(usize, usize),
    allocator: mem.Allocator,

    fn init(allocator: mem.Allocator, vocab_path: []const u8) JaideError!@This() {
        const file = try fs.cwd().openFile(vocab_path, .{});
        defer file.close();
        const vocab_buf = try file.readToEndAlloc(allocator, MAX_VOCAB_SIZE * 10);
        errdefer allocator.free(vocab_buf);
        var lines = mem.split(u8, vocab_buf, "\n");
        var vocab_list = ArrayList([]const u8).init(allocator);
        defer vocab_list.deinit();
        while (lines.next()) |line| {
            if (line.len > 0) {
                try vocab_list.append(line);
            }
        }
        const vocab_size = vocab_list.items.len;
        var vocab_flat = try allocator.alloc(u8, vocab_size * 10);
        errdefer allocator.free(vocab_flat);
        var offset: usize = 0;
        for (vocab_list.items) |word| {
            @memcpy(vocab_flat[offset..offset + word.len], word);
            offset += word.len + 1;
        }
        var inv_vocab = HashMap(usize, usize).init(allocator);
        for (0..vocab_size) |i| {
            const word_start = i * 10; // Assume max word len 10
            const hash = std.hash.Wyhash.hash(0, vocab_flat[word_start..word_start + 10]);
            try inv_vocab.put(hash, i);
        }
        return .{ .vocab = vocab_flat, .vocab_size = vocab_size, .inverse_vocab = inv_vocab, .allocator = allocator };
    }

    fn deinit(self: *@This()) void {
        self.inverse_vocab.deinit();
        self.allocator.free(self.vocab);
        self.* = undefined;
    }

    fn encode(self: *@This(), text: []const u8) JaideError![]usize {
        var tokens = ArrayList(usize).init(self.allocator);
        defer if (!tokens.expandToCapacity()) {} else {};
        var words = mem.split(u8, text, " ");
        while (words.next()) |word| {
            const word_hash = std.hash.Wyhash.hash(0, word);
            if (self.inverse_vocab.get(word_hash)) |idx| {
                try tokens.append(idx);
            } else {
                try tokens.append(0);
            }
        }
        const token_array = try self.allocator.alloc(usize, tokens.items.len);
        @memcpy(token_array, tokens.items);
        return token_array;
    }

    fn decode(self: *@This(), tokens: []const usize) JaideError![]u8 {
        var text = ArrayList(u8).init(self.allocator);
        for (tokens) |tok| {
            if (tok < self.vocab_size) {
                const word_start = tok * 10;
                const word_end = math.min(word_start + 10, self.vocab.len);
                const word = self.vocab[word_start..word_end];
                try text.appendSlice(word);
                try text.append(' ');
            }
        }
        const text_array = try self.allocator.alloc(u8, text.items.len);
        @memcpy(text_array, text.items);
        return text_array;
    }
};

const MGT = struct {
    tokenizer: MGTTokens,
    embedding_dim: usize,
    embeddings: DynamicTensor(F, .{ MAX_VOCAB_SIZE, MAX_DIM, 1 }),
    rsf: RSFProcessor,
    ssi: SSIIndex,
    ranker: Ranker,
    allocator: mem.Allocator,

    fn init(allocator: mem.Allocator, vocab_path: []const u8, embedding_dim: usize, num_layers: usize, neurons_per_layer: usize) JaideError!@This() {
        var self = @This{}{
            .tokenizer = undefined,
            .embedding_dim = embedding_dim,
            .embeddings = undefined,
            .rsf = undefined,
            .ssi = undefined,
            .ranker = undefined,
            .allocator = allocator,
        };
        self.tokenizer = try MGTTokens.init(allocator, vocab_path);
        self.embeddings = try DynamicTensor(F, .{ MAX_VOCAB_SIZE, embedding_dim, 1 }).init(allocator);
        self.rsf = try RSFProcessor.init(allocator, num_layers, neurons_per_layer, QUANTUM_QUBITS);
        self.ssi = try SSIIndex.init(allocator, 20);
        self.ranker = try Ranker.init(allocator, 8, 10000);
        errdefer {
            self.rsf.deinit();
            self.ssi.deinit();
            self.ranker.deinit();
        }
        var prng = Rng.init(456);
        var rng = prng.random();
        for (0..MAX_VOCAB_SIZE) |v| {
            for (0..embedding_dim) |d| {
                self.embeddings.set(v, d, 0, rng.float(F) * 2 - 1);
            }
        }
        return self;
    }

    fn deinit(self: *@This()) void {
        self.tokenizer.deinit();
        self.embeddings.deinit();
        self.rsf.deinit();
        self.ssi.deinit();
        self.ranker.deinit();
        self.* = undefined;
    }

    fn processSequence(self: *@This(), text: []const u8, max_len: usize) JaideError![]F {
        const tokens = try self.tokenizer.encode(text);
        defer self.allocator.free(tokens);
        const actual_len = math.min(tokens.len, max_len);
        var emb = try self.allocator.alloc(F, actual_len * self.embedding_dim);
        errdefer self.allocator.free(emb);
        for (0..actual_len) |i| {
            const tok_emb_start = i * self.embedding_dim;
            for (0..self.embedding_dim) |d| {
                emb[tok_emb_start + d] = self.embeddings.get(@as(usize, tokens[i]), d, 0);
            }
        }
        var rsf_out = try self.allocator.alloc(F, actual_len * self.embedding_dim);
        errdefer self.allocator.free(rsf_out);
        try self.rsf.process(emb, rsf_out, actual_len);
        self.allocator.free(emb);
        return rsf_out;
    }

    fn indexSequence(self: *@This(), text: []const u8, doc_id: usize) JaideError!void {
        const tokens = try self.tokenizer.encode(text);
        errdefer self.allocator.free(tokens);
        try self.ssi.insertTokens(tokens[0..math.min(tokens.len, MAX_SEQ_LEN)]);
        try self.ranker.addNgrams(tokens, doc_id);
        self.allocator.free(tokens);
    }

    pub fn generate(self: *@This(), prompt: []const u8, max_output: usize) JaideError![]u8 {
        const prompt_emb = try self.processSequence(prompt, MAX_SEQ_LEN);
        defer self.allocator.free(prompt_emb);
        const top_k = try self.ssi.retrieveTopK(&.{}, 10); // Simplified query
        defer self.allocator.free(top_k);
        const ranked = self.ranker.rankCandidates(&.{}, top_k);
        var output_tokens = ArrayList(usize).init(self.allocator);
        defer output_tokens.deinit();
        for (0..max_output) |_| {
            var next_emb = try self.allocator.alloc(F, self.embedding_dim);
            errdefer self.allocator.free(next_emb);
            var sum: F = 0;
            for (0..ranked.len) |r| {
                const leaf_tokens = &.{ @as(usize, self.ssi.leaves[ranked[r]].id) }; // Simplified
                const leaf_emb_start = 0 * self.embedding_dim; // Dummy
                for (0..self.embedding_dim) |d| {
                    next_emb[d] = prompt_emb[leaf_emb_start + d] * (@as(F, 1.0) / @as(F, @floatFromInt(ranked.len)));
                    sum += next_emb[d];
                }
            }
            const avg = if (sum > 0) 1.0 / sum else 0;
            for (0..self.embedding_dim) |d| {
                next_emb[d] *= avg;
            }
            const next_token = @as(usize, @intFromFloat(@round(math.cos(next_emb[0]) * @as(F, @floatFromInt(self.tokenizer.vocab_size)) / 2.0)));
            try output_tokens.append(math.clamp(next_token, 0, self.tokenizer.vocab_size - 1));
        }
        self.allocator.free(next_emb);
        return try self.tokenizer.decode(output_tokens.items);
    }
};

const ServerConfig = struct {
    port: u16 = 8080,
    host: [*:0]const u8 = "0.0.0.0",
    max_connections: u32 = 100,
    request_timeout_ms: u64 = 30000,
    batch_size: usize = BATCH_SIZE,
    model_path: ?[]const u8 = null,
    api_key: ?[]const u8 = null,
    rate_limit_per_minute: u32 = 10,
    max_request_size_bytes: usize = 1024 * 1024,
    require_api_key: bool = true,
};

const RateLimiter = struct {
    timestamps: ArrayList(i64),
    mutex: Mutex,
    allocator: mem.Allocator,

    fn init(allocator: mem.Allocator) @This() {
        return .{ .timestamps = ArrayList(i64).init(allocator), .mutex = .{}, .allocator = allocator };
    }

    fn deinit(self: *@This()) void {
        self.timestamps.deinit();
    }

    fn allowRequest(self: *@This(), limit: u32) bool {
        self.mutex.lock();
        defer self.mutex.unlock();
        const now = time.milliTimestamp();
        while (self.timestamps.items.len > 0 and now - self.timestamps.items[0] > 60000) {
            _ = self.timestamps.popFront();
        }
        if (self.timestamps.items.len >= limit) return false;
        try self.timestamps.append(now);
        return true;
    }
};

const RequestLog = struct {
    timestamps: ArrayList(i64),
    mutex: Mutex,
    logs: StringHashMap(@This()),
    allocator: mem.Allocator,

    fn init(allocator: mem.Allocator) @This() {
        return .{ .timestamps = ArrayList(i64).init(allocator), .mutex = .{}, .logs = StringHashMap(@This()).init(allocator), .allocator = allocator };
    }

    fn deinit(self: *@This()) void {
        self.timestamps.deinit();
        var it = self.logs.iterator();
        while (it.next()) |entry| {
            entry.value_ptr.deinit();
        }
        self.logs.deinit();
    }
};

pub const InferenceServer = struct {
    config: ServerConfig,
    mgt: MGT,
    rate_limiter: RateLimiter,
    request_logger: RequestLog,
    server: net.StreamServer,
    allocator: mem.Allocator,
    running: Atomic(bool),

    fn init(allocator: mem.Allocator, config: ServerConfig, vocab_path: []const u8) JaideError!*@This() {
        const self = try allocator.create(@This());
        errdefer allocator.destroy(self);
        self.* = .{
            .config = config,
            .mgt = try MGT.init(allocator, vocab_path, MAX_DIM, 12, 1024),
            .rate_limiter = RateLimiter.init(allocator),
            .request_logger = RequestLog.init(allocator),
            .allocator = allocator,
            .running = Atomic(bool).init(false),
            .server = undefined,
        };
        errdefer {
            self.mgt.deinit();
            self.rate_limiter.deinit();
            self.request_logger.deinit();
        }
        try self.startServer();
        return self;
    }

    fn deinit(self: *@This()) void {
        self.running.store(false, .SeqCst);
        self.server.deinit();
        self.mgt.deinit();
        self.rate_limiter.deinit();
        self.request_logger.deinit();
        self.allocator.destroy(self);
    }

    fn startServer(self: *@This()) JaideError!void {
        const address = try net.Address.parseIp(self.config.host, self.config.port);
        self.server = net.StreamServer.init(.{ .reuse_address = true });
        try self.server.listen(address);
        self.running.store(true, .SeqCst);
        const thread_fn = struct {
            fn run(srv: *InferenceServer) void {
                while (srv.running.load(.SeqCst)) {
                    const conn = srv.server.accept() catch |err| {
                        std.debug.print("Accept error: {}\n", .{err});
                        continue;
                    };
                    _ = thread.spawn(.{}, handleConnection, .{ srv, conn.stream });
                }
            }
        }.run;
        _ = try thread.spawn(.{}, thread_fn, .{self});
    }

    fn handleConnection(srv: *InferenceServer, stream: net.Stream) void {
        defer stream.close();
        var buffer: [1024 * 1024]u8 = undefined;
        const read_len = stream.read(&buffer) catch |err| {
            std.debug.print("Read error: {}\n", .{err});
            return;
        };
        const request_slice = buffer[0..read_len];
        const parsed = std.http.parse(&.{}, request_slice, &.{}, &.{}) catch |err| {
            stream.writeAll("HTTP/1.1 400 Bad Request\r\n\r\n") catch {};
            return;
        };
        if (parsed.status != .ok) {
            stream.writeAll("HTTP/1.1 400 Bad Request\r\n\r\n") catch {};
            return;
        }
        if (!srv.rate_limiter.allowRequest(srv.config.rate_limit_per_minute)) {
            stream.writeAll("HTTP/1.1 429 Too Many Requests\r\n\r\n") catch {};
            return;
        }
        if (srv.config.require_api_key and !checkApiKey(request_slice, srv.config.api_key.?)) {
            stream.writeAll("HTTP/1.1 401 Unauthorized\r\n\r\n") catch {};
            return;
        }
        const body = parseJsonBody(request_slice) catch |err| {
            stream.writeAll("HTTP/1.1 400 Bad Request\r\n\r\n") catch {};
            return;
        };
        const prompt = body.get("prompt").?.string.?;
        const max_output = body.get("max_tokens").?.integer orelse 100;
        const generation = srv.mgt.generate(prompt, @as(usize, @intCast(max_output))) catch |err| {
            stream.writeAll("HTTP/1.1 500 Internal Server Error\r\n\r\n") catch {};
            return;
        };
        defer srv.allocator.free(generation);
        const response = std.fmt.allocPrint(srv.allocator, "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\n\r\n{{\"text\":\"", .{}) catch |err| {
            stream.writeAll("HTTP/1.1 500 Internal Server Error\r\n\r\n") catch {};
            return;
        };
        defer srv.allocator.free(response);
        const full_response = std.fmt.allocPrint(srv.allocator, "{s}{s}\"}", .{ response, generation }) catch |err| {
            stream.writeAll("HTTP/1.1 500 Internal Server Error\r\n\r\n") catch {};
            return;
        };
        defer srv.allocator.free(full_response);
        stream.writeAll(full_response) catch {};
    }
};

fn checkApiKey(request: []const u8, key: []const u8) bool {
    const header_end = mem.indexOf(u8, request, "\r\n") orelse 0;
    const first_line = request[0..header_end];
    const auth_start = mem.indexOf(u8, first_line, "Authorization: ") orelse return false;
    const auth_value = first_line[auth_start + 15 ..];
    return mem.eql(u8, auth_value, key);
}

fn parseJsonBody(request: []const u8) !std.json.Value {
    const body_start = mem.indexOf(u8, request, "\r\n\r\n") orelse return JaideError.JsonParseError;
    const body = request[body_start + 4 ..];
    return std.json.parseFromSlice(std.json.Value, body, .{ .allocate = true }) catch JaideError.JsonParseError;
}

pub fn main() !void {
    var gpa = GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    var config = ServerConfig{};
    const vocab_path = "app/vocab.json";
    const server = try InferenceServer.init(allocator, config, vocab_path);
    defer server.deinit();

    std.debug.print("Jaide Inference Server started on port {}\n", .{config.port});

    while (server.running.load(.SeqCst)) {
        std.time.sleep(1000000000);
    }
}

